package com.trainflow.program;
import static org.mockito.Mockito.*; import com.trainflow.ai.OllamaClient; import com.trainflow.trainer.Trainer; import com.trainflow.trainingcase.*; import com.trainflow.trainingneed.*; import java.math.BigDecimal; import java.util.*; import org.junit.jupiter.api.Test;
class OllamaProgramGenerationGatewayTest {@Test void routesProgramToPrestacodeModelWithoutRawCv(){OllamaClient client=mock(OllamaClient.class);TrainingCaseRepository cases=mock(TrainingCaseRepository.class);TrainingNeedRepository needs=mock(TrainingNeedRepository.class);var company=new com.trainflow.company.Company("Acme");var tc=new TrainingCase("TR-1",company,"Cybersecurity",UUID.randomUUID());Trainer trainer=new Trainer("Amina");tc.setTrainer(trainer);TrainingNeed need=new TrainingNeed(tc.getId());need.setTargetAudience("Beginners");need.setObjectives("Secure email");need.setPlannedDaysCount(1);need.setDurationHours(new BigDecimal("7"));when(cases.detailed(tc.getId())).thenReturn(Optional.of(tc));when(needs.findByTrainingCaseId(tc.getId())).thenReturn(Optional.of(need));when(client.generateJson(anyString(),anyString(),anyString(),anyInt())).thenReturn(Map.of("title","Cybersecurity"));new OllamaProgramGenerationGateway(client,cases,needs,"qwen-prestacode-v3:latest","1h",4096).generate(tc.getId());verify(client).generateJson(eq("qwen-prestacode-v3:latest"),argThat(p->!p.contains("raw_text")&&!p.contains("storage_filename")),eq("1h"),eq(4096));}}
